test('cancel retains the persisted draft; explicit discard clears it and restores disk buffer',async()=>{const h=harness();attach(h);h.get('editor').value='draft';h.ui.state.dirty=true;h.ui.persistDocumentDraft();const cancel=h.ui.canLeave();h.get('unsaved-dialog').close('cancel');assert.equal(await cancel,false);assert.equal(h.ui.drafts().document('root:note.md').text,'draft');const discard=h.ui.canLeave();h.get('unsaved-dialog').close('discard');assert.equal(await discard,true);assert.equal(h.ui.drafts().document('root:note.md'),null);assert.equal(h.get('editor').value,'磁盘正文');});
test('concurrent save is blocked and typing during save becomes a draft on the new base SHA',async()=>{const h=harness();attach(h);h.get('editor').value='submitted';h.ui.state.dirty=true;const save=h.ui.saveNote();await h.ui.saveNote();assert.equal(h.requests.length,1);h.get('editor').value='typed during save';h.requests[0].respond({id:'root:note.md',text:'submitted',sha:'sha-b',undo_id:'u1'});await save;assert.equal(h.ui.state.dirty,true);assert.equal(h.ui.drafts().document('root:note.md').text,'typed during save');assert.equal(h.ui.drafts().document('root:note.md').base_sha,'sha-b');assert.equal(h.ui.drafts().undo('root:note.md').id,'u1');});
test('successful save clears its persisted draft and keeps its SHA receipt visible',async()=>{const h=harness();attach(h);h.get('editor').value='submitted';h.ui.state.dirty=true;const save=h.ui.saveNote();h.requests[0].respond({text:'submitted',sha:'sha-b',undo_id:'u1'});await save;assert.equal(h.ui.drafts().document('root:note.md'),null);assert.match(h.get('file-state').textContent,/sha-b/);});
test('A to B to A rejects both stale status responses even when abort is ignored',async()=>{const h=harness();h.ui.state.session='a';const oldA=h.ui.pollChat();const b=h.ui.selectSession('b');const newA=h.ui.selectSession('a');assert.equal(h.requests.length,3);h.requests[2].respond({messages:[{id:'latest',role:'assistant',text:'new A'}],jobs:[]});await newA;h.requests[0].respond({messages:[{id:'old',role:'assistant',text:'stale A'}],jobs:[]});h.requests[1].respond({messages:[{id:'wrong',role:'assistant',text:'B'}],jobs:[]});await Promise.all([oldA,b]);assert.equal(h.ui.state.messages.map(m=>m.id).join(','),'latest');});
test('session switching restores separate inputs and initial restore never overwrites the new-chat draft',async()=>{const h=harness();h.ui.drafts().saveChat('','new draft');h.ui.drafts().saveChat('a','A draft');const first=h.ui.selectSession('a',true);h.requests[0].respond({messages:[],jobs:[]});await first;assert.equal(h.get('message').value,'A draft');h.get('message').value='edited A';await h.ui.selectSession('');assert.equal(h.get('message').value,'new draft');assert.equal(h.ui.drafts().chat('a'),'edited A');});
test('uncertain or cancelled receipts never say successfully written or expose undo',()=>{const h=harness();for(const status of ['uncertain','cancelled',undefined]){const html=h.ui.referenceHTML({write_receipts:[{id:'doc',title:'文档',status,sha:'s',undo_id:'u'}]});assert.doesNotMatch(html,/已写入并回读核对|data-undo=/);}assert.match(h.ui.referenceHTML({write_receipts:[{id:'doc',status:'verified',sha:'s',undo_id:'u'}]}),/data-undo=/);});
test('undone receipt state survives render and retains no model credentials',()=>{const h=harness();h.ui.drafts().markUndone('u');assert.match(h.ui.referenceHTML({write_receipts:[{id:'doc',status:'verified',sha:'s',undo_id:'u'}]}),/已撤销写入/);assert.doesNotMatch([...h.storage.map.values()].join(''),/token|credential|api_key/);});
test('unsafe markup and protocols stay inert while vault citations remain actionable',()=>{const h=harness(),md=h.ui.markdown;assert.doesNotMatch(md('<img src=x onerror=bad>'),/<img/);for(const url of ['javascript:bad','file:///etc/passwd','data:text/html,bad'])assert.doesNotMatch(md(`[bad](${url})`),/data-open=|href=/);assert.match(md('[顾问](vault:advisor:SKILL.md)'),/data-open="advisor:SKILL.md"/);});
test('new recovery and pagination controls exist and original theme tokens remain unchanged',()=>{const html=fs.readFileSync(path.join(__dirname,'../web/workspace.html'),'utf8'),css=fs.readFileSync(path.join(__dirname,'../web/workspace.css'),'utf8');assert.match(html,/id="chat-draft-state"/);assert.match(html,/id="more-sessions"/);for(const token of ['--blue:#1e40af','--bg:#f6f7fb','--line:#dbeafe','--radius:14px',"--scene:url('/scene.png')"])assert.ok(css.includes(token),token);});
test('a save conflict immediately locks further writes while retaining the draft',async()=>{const h=harness();attach(h);h.get('editor').value='conflicting draft';h.ui.state.dirty=true;const save=h.ui.saveNote();h.requests[0].respond({error:'conflict'},409);await save;assert.equal(h.ui.state.draftConflict,true);assert.equal(h.get('save-note').disabled,true);assert.equal(h.ui.drafts().document('root:note.md').text,'conflicting draft');await h.ui.saveNote();assert.equal(h.requests.length,1);});
test('in-memory undone receipts remain undone even if persistent storage is unavailable',()=>{const h=harness();h.ui.state.undoneReceipts.add('u-memory');assert.match(h.ui.referenceHTML({write_receipts:[{id:'doc',status:'verified',sha:'s',undo_id:'u-memory'}]}),/已撤销写入/);});
test('connection dialog reads credential status but neither opens nor refreshes a model trial',async()=>{const h=harness();h.get('connection-settings').fire('click');assert.equal(h.get('connection-dialog').open,true);assert.equal(h.requests.length,1);assert.equal(h.requests[0].url,'/api/providers');assert.equal(h.requests[0].options.method||'GET','GET');h.requests[0].respond({providers:[{id:'codex',configured:true},{id:'deepseek',configured:false,can_save:true}]});await settle();assert.match(h.get('deepseek-connection-status').textContent,/尚未接入/);h.get('refresh-models').fire('click');assert.equal(h.requests.length,2);assert.equal(h.requests[1].url,'/api/models?refresh=1');assert.equal(h.requests[1].options.method||'GET','GET');h.requests[1].respond({models:[]});await settle();assert.match(h.get('chat-notice').textContent,/当前账户目录已读取.*未试答模型也可选择/);assert.equal(h.requests.some(r=>r.url.includes('/check')),false);});
test('bootstrap and selected document/session state are data-directory scoped',()=>{assert.match(source,/request\('\/api\/bootstrap'\)/);assert.doesNotMatch(source,/request\('\/api\/state'\)/);assert.match(source,/encodeURIComponent\(state.storageScope\)/);const css=fs.readFileSync(path.join(__dirname,'../web/workspace.css'),'utf8');assert.match(css,/--paper:#f3f8ff/);assert.match(css,/--sidebar:#eef5ff/);});

test('sessions pagination keeps fifty current and older sessions available across refresh',async()=>{const h=harness(),first=Array.from({length:50},(_,i)=>({id:'s'+(100-i),title:'S'+(100-i)}));const initial=h.ui.loadSessions();h.requests[0].respond({sessions:first,pagination:{has_more:true,next_cursor:51}});await initial;assert.equal(h.ui.state.sessions.length,50);const more=h.ui.loadSessions(true);assert.match(h.requests[1].url,/before=51/);h.requests[1].respond({sessions:[{id:'s50',title:'older'}],pagination:{has_more:false,next_cursor:null}});await more;assert.equal(h.ui.state.sessions.length,51);assert.equal(h.get('more-sessions').hidden,true);const refresh=h.ui.loadSessions();h.requests[2].respond({sessions:first,pagination:{has_more:true,next_cursor:51}});await settle();assert.match(h.requests[3].url,/before=51&limit=1/);h.requests[3].respond({sessions:[{id:'s50',title:'older refreshed'}],pagination:{has_more:false,next_cursor:null}});await refresh;assert.equal(h.ui.state.sessions.length,51);assert.equal(h.ui.state.sessions.at(-1).id,'s50');assert.equal(h.get('more-sessions').hidden,true);});

test('undo pending locks editor and preserves even programmatic new input with conflict state',async()=>{const h=harness();attach(h);h.ui.state.undo={id:'u1',sha:'sha-a'};const pending=h.ui.undoSave();await settle();assert.equal(h.get('editor').readOnly,true);h.get('editor').value='输入期间新文字';h.get('editor').fire('input');h.ui.persistDocumentDraft();h.requests[0].respond({id:'root:note.md',text:'撤销磁盘正文',sha:'undo-sha'});await pending;assert.equal(h.requests.length,1);assert.equal(h.get('editor').value,'输入期间新文字');assert.equal(h.ui.state.draftConflict,true);assert.equal(h.ui.state.dirty,true);assert.equal(h.ui.drafts().document('root:note.md').text,'输入期间新文字');assert.equal(h.get('editor').readOnly,false);});
test('create delayed response never forcibly opens over new input',async()=>{const h=harness();attach(h);h.get('new-note-path').value='created.md';h.get('new-note-root').value='root';const pending=h.ui.createNote({preventDefault(){}});await settle();h.get('editor').value='current draft';h.get('editor').fire('input');h.ui.persistDocumentDraft();h.requests[0].respond({id:'root:created.md'});await settle();assert.match(h.requests[1].url,/vault\/roots/);h.requests[1].respond({roots:[]});await pending;assert.equal(h.requests.length,2);assert.equal(h.ui.state.file.id,'root:note.md');assert.equal(h.get('editor').value,'current draft');assert.equal(h.ui.drafts().document('root:note.md').text,'current draft');});
test('AI receipt undo preserves newly typed draft and detects disk conflict',async()=>{const h=harness();attach(h);const button=element('undo');button.dataset={undo:'u1',sha:'sha-a'};const pending=h.ui.undoReceipt(button);await settle();h.get('editor').value='new during AI undo';h.get('editor').fire('input');h.ui.persistDocumentDraft();h.requests[0].respond({id:'root:note.md',sha:'undo-sha'});await settle();h.requests[1].respond({id:'root:note.md',sha:'undo-sha'});await pending;assert.equal(h.get('editor').value,'new during AI undo');assert.equal(h.ui.state.draftConflict,true);assert.equal(h.ui.drafts().document('root:note.md').text,'new during AI undo');});
test('chat storage failures block session navigation and retain unsent text',async()=>{for(const storage of [null,{getItem(){return null;},setItem(){throw Error('quota');},removeItem(){throw Error('quota');}}])for(const target of ['','b']){const h=harness();h.ui.useStorage(storage);h.ui.state.session='a';h.get('message').value='未发送问题';h.get('session-select').value=target;await h.ui.selectSession(target);assert.equal(h.ui.state.session,'a');assert.equal(h.get('session-select').value,'a');assert.equal(h.get('message').value,'未发送问题');assert.equal(h.get('chat-draft-state').hidden,false);assert.equal(h.requests.length,0);}});

test('connection labels use wiki aliases and Markdown text without changing link targets',()=>{const h=harness(),target='项目/今天做视频--977babcdef123456.md',file_id='upward:encoded-original';const wiki=h.ui.connectionLink({target,file_id,title:'今天做视频--977babcdef123456'},'[[项目/今天做视频--977babcdef123456.md|今天做视频]]');assert.equal(wiki.label,'今天做视频');assert.equal(wiki.id,file_id);assert.equal(wiki.target,target);const md=h.ui.connectionLink({target,file_id,title:target},'[我的视频计划](项目/今天做视频--977babcdef123456.md)');assert.equal(md.label,'我的视频计划');assert.equal(md.target,target);const fallback=h.ui.connectionLink({target,file_id,title:target},'');assert.equal(fallback.label,'今天做视频');assert.equal(fallback.id,file_id);});
test('connection buttons keep backend document IDs, ignore code examples, and use readable backlinks',async()=>{const h=harness();attach(h,{text:'```md\n[[a.md|伪别名]]\n```\n[[a.md|真实别名]]'});h.ui.state.file.links=[{target:'a.md',file_id:'root:real-a.md',title:'a'}];h.ui.state.file.backlinks=[{file_id:'root:real-b.md',title:'来源--977babcdef123456'}];h.ui.renderConnections();const buttons=h.get('connections').children.filter(x=>x.listeners.click);assert.equal(buttons[0].textContent,'真实别名');assert.equal(buttons[1].textContent,'来源');buttons[0].fire('click');await settle();assert.match(h.requests[0].url,/id=root%3Areal-a.md/);});

test('growth-view send transmits purpose and scope but never attaches a hidden previous document',async()=>{const h=harness();attach(h);h.ui.state.workspaceView='review';h.ui.state.growthContext={purpose:'review',scope:'personal',days:30,advisor_names:['naval-perspective']};h.ui.state.selectedModel='verified-model';h.get('message').value='阶段复盘';const pending=h.ui.sendMessage({preventDefault(){}});const payload=JSON.parse(h.requests[0].options.body);assert.equal(payload.purpose,'review');assert.equal(payload.days,30);assert.equal(payload.current_file_id,undefined);assert.equal(payload.allow_write,false);assert.deepEqual(payload.advisor_names,['naval-perspective']);h.requests[0].respond({error:'test intercepted'},400);await pending;assert.equal(h.get('message').value,'阶段复盘');});
test('document scope rejects missing visible attachment before model submission',async()=>{const h=harness();attach(h);h.ui.state.workspaceView='daily';h.ui.state.growthContext={purpose:'daily',scope:'document',days:7,advisor_names:[]};h.ui.state.selectedModel='verified';h.get('message').value='test';await h.ui.sendMessage({preventDefault(){}});assert.equal(h.requests.length,0);assert.match(h.get('chat-notice').textContent,/先打开并附上/);});


test('attachments enforce size/count/type before upload and retain explicit failures',async()=>{const h=harness();await h.ui.addAttachments([{name:'too.pdf',size:20971521},{name:'bad.exe',size:2}]);assert.equal(h.requests.length,0);assert.match(h.get('chat-notice').textContent,/暂不支持/);const upload=h.ui.addAttachments([{name:'ok.md',size:5}]);await settle();assert.equal(h.ui.currentAttachments()[0].status,'uploading');assert.equal(h.get('send').disabled,true);assert.equal(h.requests[0].url,'/api/workspace/attachments');h.requests[0].respond({error:'解析失败'},400);await upload;assert.equal(h.ui.currentAttachments()[0].status,'failed');assert.match(h.get('attachment-list').innerHTML,/解析失败/);h.ui.removeAttachment(h.ui.currentAttachments()[0].key);assert.equal(h.ui.currentAttachments().length,0);for(let i=0;i<8;i++)h.ui.currentAttachments().push({id:String(i),name:'n',status:'ready'});await h.ui.addAttachments([{name:'ninth.md',size:1}]);assert.equal(h.requests.length,1);assert.match(h.get('chat-notice').textContent,/最多添加 8/);});
test('upload completion stays with original session, stores no path or binary, and removal cannot resurrect it',async()=>{const h=harness();h.ui.state.session='A';const upload=h.ui.addAttachments([{name:'n.md',size:5}]);await settle();const key=h.ui.currentAttachments()[0].key;h.ui.removeAttachment(key);await h.ui.selectSession('');h.requests[0].respond({attachment:{id:'att-a',name:'n.md',bytes:5,status:'ready',path:'/private/secret',data_base64:'secret'}});await settle();assert.equal(h.requests[1].url,'/api/workspace/attachments/remove');h.requests[1].respond({deleted:true});await upload;assert.equal(h.ui.currentAttachments().length,0);assert.equal(h.ui.drafts().attachments('A').length,0);assert.doesNotMatch([...h.storage.map.values()].join(''),/private|data_base64/);});
test('ready attachments recover separately and pure attachment send uses IDs only',async()=>{const h=harness();h.ui.drafts().saveAttachments('A',[{id:'att-a',key:'a',name:'photo.png',status:'ready',bytes:5}]);const selecting=h.ui.selectSession('A',true);h.requests[0].respond({messages:[],jobs:[]});await selecting;assert.equal(h.ui.currentAttachments()[0].id,'att-a');h.ui.state.selectedModel='verified';h.ui.updateChatControls();assert.equal(h.get('send').disabled,false);const sending=h.ui.sendMessage({preventDefault(){}});const body=JSON.parse(h.requests[1].options.body);assert.deepEqual(body.attachment_ids,['att-a']);assert.equal(body.message,'');h.requests[1].respond({error:'intercept'},400);await sending;assert.equal(h.ui.currentAttachments()[0].id,'att-a');});
test('native speech only starts on click, ignores stale result and inserts editable text without send',async()=>{const h=harness(),calls=[];h.window.upwardNativeSpeech=true;h.window.webkit={messageHandlers:{upwardSpeech:{postMessage:v=>calls.push(v)}}};assert.equal(calls.length,0);h.get('message').value='已写内容';h.ui.toggleSpeech();assert.equal(calls[0].action,'start');const ticket=h.ui.state.speech;h.window.fire('upward-speech',{detail:{state:'result',request_id:'old',text:'错误文字'}});assert.equal(h.get('message').value,'已写内容');h.window.fire('upward-speech',{detail:{state:'result',request_id:ticket.id,text:'新的口述',final:true}});assert.equal(h.get('message').value,'已写内容\n新的口述');assert.equal(h.requests.length,0);assert.equal(h.ui.state.speech,null);h.ui.toggleSpeech();h.ui.cancelSpeech();h.window.fire('upward-speech',{detail:{state:'result',request_id:ticket.id,text:'迟到'}});assert.doesNotMatch(h.get('message').value,/迟到/);assert.equal(calls.at(-1).action,'cancel');});
test('unsupported speech gives real fallback and browser recognizer ignores results after cancellation',()=>{const h=harness();h.ui.toggleSpeech();assert.match(h.get('speech-status').textContent,/系统设置 → 键盘 → 听写/);let recognizer;h.window.SpeechRecognition=class{constructor(){recognizer=this;}start(){}abort(){}stop(){}};h.ui.toggleSpeech();h.ui.cancelSpeech();recognizer.onresult({resultIndex:0,results:[Object.assign([{transcript:'late'}],{isFinal:true})]});assert.equal(h.get('message').value,'');assert.equal(h.requests.length,0);});
test('scope and execution capabilities are distinct, scoped request forces knowledge mode',async()=>{const h=harness();h.ui.state.options={execution_modes:[{id:'assistant',label:'本机助手'},{id:'knowledge',label:'资料顾问'}],capabilities:{native_tools:true,web_search:true,attachments:{enabled:true}}};h.ui.state.growthContext={purpose:'learn',scope:'advisors',days:7,advisor_names:[]};h.ui.renderCapabilities();assert.equal(h.get('execution-mode').value,'knowledge');assert.equal(h.get('execution-mode').disabled,true);assert.match(h.get('execution-note').textContent,/不会启用本机助手/);h.ui.state.selectedModel='verified';h.get('message').value='question';const sending=h.ui.sendMessage({preventDefault(){}});assert.equal(JSON.parse(h.requests[0].options.body).execution_mode,'knowledge');h.requests[0].respond({error:'intercept'},400);await sending;h.ui.state.growthContext.scope='personal';h.ui.renderCapabilities();assert.equal(h.get('execution-mode').value,'assistant');assert.match(h.get('capabilities-detail').textContent,/不代表所有桌面插件/);});
test('requests never auto approve, required input blocks, failure retains answers and duplicate click is blocked',async()=>{const h=harness();h.ui.state.jobs=[{id:'j',status:'waiting_input',requests:[{id:'r',kind:'input',status:'pending',summary:'<script>unsafe</script>',questions:[{id:'q',label:'选择',required:true}]}]}];h.ui.renderNativeRequests();assert.equal(h.requests.length,0);assert.match(h.get('native-requests').innerHTML,/&lt;script&gt;/);await h.ui.respondToRequest('j','r','submit');assert.equal(h.requests.length,0);h.ui.state.requestAnswers.set('j:r',{q:['保留答案']});const pending=h.ui.respondToRequest('j','r','submit');await h.ui.respondToRequest('j','r','submit');assert.equal(h.requests.length,1);assert.deepEqual(JSON.parse(h.requests[0].options.body).answers,{q:['保留答案']});h.requests[0].respond({error:'offline'},500);await pending;assert.deepEqual(h.ui.state.requestAnswers.get('j:r'),{q:['保留答案']});assert.match(h.get('native-requests').innerHTML,/offline/);assert.equal(h.ui.state.jobs[0].requests[0].status,'pending');});
