test('DeepSeek credentials use a password input and remain outside recovery and public messages',async()=>{
 const html=fs.readFileSync(path.join(__dirname,'../web/workspace.html'),'utf8');assert.match(html,/id="deepseek-api-key" type="password" autocomplete="off"/);assert.doesNotMatch(html,/id="deepseek-api-key"[^>]*value=/);assert.match(html,/\/docs\/deepseek-and-codex.md/);assert.match(html,/网页 \/ App 账号不能直接代替 API 密钥/);
 const h=harness(),fake='synthetic-private-value-for-test';h.ui.providers.items=publicProviders().providers;h.get('message').value='保留问题';h.ui.persistChatDraft();h.ui.currentAttachments().push({id:'attachment',key:'attachment',name:'公开.md',status:'ready'});h.get('deepseek-api-key').value=fake;
 const saving=h.ui.saveDeepSeek({preventDefault(){}});assert.equal(h.get('deepseek-api-key').value,'');assert.equal(h.get('model-select').disabled,true);assert.equal(h.requests[0].url,'/api/providers/deepseek');assert.deepEqual(JSON.parse(h.requests[0].options.body),{api_key:fake});
 h.requests[0].respond(publicProviders(true));await settle();assert.equal(h.requests[1].url,'/api/models?refresh=1');h.requests[1].respond({models:[publicDeepSeekModel],default_id:publicDeepSeekModel.id});await saving;
 assert.equal(h.requests.length,2);assert.equal(h.get('deepseek-api-key').value,'');assert.equal(h.get('message').value,'保留问题');assert.equal(h.ui.currentAttachments().length,1);assert.match(h.get('provider-notice').textContent,/尚未发起试答/);assert.equal([...h.storage.map.values()].join('').includes(fake),false);assert.equal(JSON.stringify(h.ui.state).includes(fake),false);assert.equal(JSON.stringify(h.ui.providers).includes(fake),false);
});
test('credential save failure clears its field and redacts even an echoed error without losing buffers',async()=>{
 const h=harness(),fake='synthetic-error-private-value';h.ui.providers.items=publicProviders().providers;h.get('deepseek-api-key').value=fake;h.get('message').value='未发送问题';h.ui.currentAttachments().push({id:'a',key:'a',name:'证据.md',status:'ready'});const saving=h.ui.saveDeepSeek({preventDefault(){}});h.requests[0].respond({error:'rejected '+fake},400);await saving;
 assert.equal(h.requests.length,1);assert.equal(h.get('deepseek-api-key').value,'');assert.equal(h.get('provider-notice').textContent.includes(fake),false);assert.match(h.get('provider-notice').textContent,/已隐藏/);assert.equal(h.get('message').value,'未发送问题');assert.equal(h.ui.currentAttachments().length,1);
});
test('closing or cancelling connection settings clears only the secret and performs no write',()=>{
 for(const event of ['close','cancel']){const h=harness();h.get('message').value='现有草稿';h.ui.currentAttachments().push({id:'a',key:'a',name:'材料.md',status:'ready'});h.get('deepseek-api-key').value='synthetic-unsaved-key';h.get('connection-dialog').fire(event);assert.equal(h.get('deepseek-api-key').value,'');assert.equal(h.get('message').value,'现有草稿');assert.equal(h.ui.currentAttachments().length,1);assert.equal(h.requests.length,0);}
});
test('environment credentials and unavailable status cannot be overwritten or removed by a form event',async()=>{
 for(const items of [publicProviders(true,false,'environment').providers,null]){const h=harness();h.ui.providers.items=items;h.get('deepseek-api-key').value='synthetic-only';h.ui.renderProviders();assert.equal(h.get('deepseek-api-key').disabled,true);assert.equal(h.get('save-deepseek').disabled,true);assert.equal(h.get('remove-deepseek').disabled,true);await h.ui.saveDeepSeek({preventDefault(){}});await h.ui.saveDeepSeek(null,true);assert.equal(h.requests.length,0);if(items)assert.match(h.get('deepseek-connection-status').textContent,/环境变量.*只读/);}
 const h=harness(),loading=h.ui.loadProviders();h.requests[0].respond({error:'local unavailable'},503);await loading;assert.match(h.get('provider-notice').textContent,/尚未读到/);assert.equal(h.get('save-deepseek').disabled,true);
});
test('removing DeepSeek preserves its history and choice as unavailable rather than silently choosing Codex',async()=>{
 const h=harness();await setPublicModels(h);h.ui.state.selectedModel=publicDeepSeekModel.id;h.ui.state.session='same-conversation';h.ui.state.messages=[{id:'old',role:'assistant',text:'历史'}];h.get('message').value='当前问题';h.ui.providers.items=publicProviders(true).providers;const removing=h.ui.saveDeepSeek(null,true);assert.deepEqual(JSON.parse(h.requests[1].options.body),{remove:true});h.requests[1].respond(publicProviders(false));await settle();h.requests[2].respond({models:[{id:'codex-model',service_id:'codex',selectable:true}],default_id:'codex-model'});await removing;
 assert.equal(h.ui.state.selectedModel,publicDeepSeekModel.id);assert.equal(h.ui.state.modelUnavailable,true);assert.equal(h.get('send').disabled,true);assert.equal(h.get('chat-service').textContent,'DeepSeek');assert.equal(h.ui.state.session,'same-conversation');assert.equal(h.ui.state.messages[0].text,'历史');assert.equal(h.get('message').value,'当前问题');assert.match(h.get('provider-notice').textContent,/历史对话已保留/);
});
test('model switching stays in one visible conversation and preserves drafts attachments and history',async()=>{
 const h=harness();await setPublicModels(h);h.ui.state.session='same';h.ui.state.messages=[{id:'previous',role:'assistant',text:'已有上下文'}];h.get('message').value='继续这个话题';h.ui.persistChatDraft();h.ui.currentAttachments().push({id:'a',key:'a',name:'公开.md',status:'ready'});h.ui.shared.preview={preview_id:'old'};const count=h.requests.length;
 h.get('model-select').value=publicDeepSeekModel.id;h.get('model-select').fire('change');assert.equal(h.ui.state.session,'same');assert.equal(h.ui.state.messages[0].text,'已有上下文');assert.equal(h.get('message').value,'继续这个话题');assert.equal(h.ui.drafts().chat('same'),'继续这个话题');assert.equal(h.ui.currentAttachments().length,1);assert.equal(h.ui.shared.preview,null);assert.equal(h.get('chat-service').textContent,'DeepSeek');assert.match(h.get('model-select').title,/发往 DeepSeek API/);assert.match(h.get('send').title,/发送给 DeepSeek API/);assert.equal(h.requests.length,count);
 const payload=h.ui.sharedPayload();assert.equal(payload.model,publicDeepSeekModel.id);assert.equal(payload.session_id,'same');assert.equal(payload.provider,undefined);assert.equal(payload.service_id,undefined);
});
test('running a round prevents programmatic provider switching and credential mutation',async()=>{
 const h=harness();await setPublicModels(h);h.ui.state.jobs=[{id:'active',status:'running'}];h.ui.providers.items=publicProviders(true).providers;h.get('deepseek-api-key').value='synthetic-value';h.ui.updateChatControls();assert.equal(h.get('model-select').disabled,true);assert.equal(h.get('save-deepseek').disabled,true);h.get('model-select').value=publicDeepSeekModel.id;h.get('model-select').fire('change');assert.equal(h.ui.state.selectedModel,'codex-model');await h.ui.saveDeepSeek({preventDefault(){}});assert.equal(h.requests.length,1);
});
test('historical and in-progress replies identify their actual service independently of current selection',()=>{
 const h=harness();h.ui.state.messages=[{id:'old',role:'assistant',text:'Codex回答',reply_context:{actual_model:'model-a'}},{id:'new',role:'assistant',text:'DeepSeek回答',reply_context:{service_id:'deepseek',service_label:'DeepSeek API',actual_model:'deepseek-flash'}}];h.ui.state.jobs=[{id:'j',status:'running',service_id:'deepseek',service_label:'DeepSeek API'}];h.ui.renderConversation();const html=h.get('conversation').innerHTML;assert.match(html,/Codex · model-a/);assert.match(html,/DeepSeek API · deepseek-flash/);assert.match(html,/DeepSeek API 正在处理/);
});
test('unsupported image inputs fail visibly before shared preview or send and remain attached',async()=>{
 const h=harness(),textOnly={...publicDeepSeekModel,input_modalities:['text']};await setPublicModels(h,[textOnly]);h.get('message').value='看图片';h.ui.currentAttachments().push({id:'pic',key:'pic',name:'公开.png',kind:'image',status:'ready'});await h.ui.sendMessage({preventDefault(){}});assert.equal(h.requests.length,1);assert.match(h.get('chat-notice').textContent,/未提供图片输入.*已保留/);h.ui.shared.selected.set('share','v');h.ui.shared.scope={};await h.ui.previewSharedSend();assert.equal(h.requests.length,1);assert.equal(h.ui.currentAttachments().length,1);assert.equal(h.get('message').value,'看图片');
});
test('DeepSeek model capabilities and billing notes are distinct from Codex abilities',async()=>{
 const h=harness();await setPublicModels(h,[publicDeepSeekModel]);h.ui.state.options={execution_modes:[{id:'assistant',label:'本机助手'},{id:'knowledge',label:'资料顾问'}],capabilities:{attachments:{enabled:true},native_tools:true,web_search:true}};h.ui.renderCapabilities();assert.match(h.get('capabilities-detail').textContent,/本轮服务：DeepSeek API/);assert.match(h.get('capabilities-detail').textContent,/未提供内置搜索/);assert.match(h.get('capabilities-detail').textContent,/提供图片输入/);assert.match(h.get('capabilities-detail').textContent,/按本人的开放平台账户计费/);
 h.ui.state.modelOptions.set(publicDeepSeekModel.id,{...publicDeepSeekModel,web_search:true});h.ui.renderCapabilities();assert.match(h.get('capabilities-detail').textContent,/内置搜索，额外 API 计费/);
});
test('trial is explicit for the selected stable model and verifies only a matching completion receipt',async()=>{
 const h=harness();await setPublicModels(h,[publicDeepSeekModel]);const checking=h.ui.checkSelectedModel();assert.equal(h.requests[1].url,'/api/models/check');assert.deepEqual(JSON.parse(h.requests[1].options.body),{model:publicDeepSeekModel.id});assert.equal(h.get('model-select').disabled,true);h.requests[1].respond({status:'running',models:[publicDeepSeekModel.id],results:[]});await checking;assert.equal(h.ui.providers.checking,true);assert.equal(h.get('check-model').textContent,'停止试答');const timer=[...h.timers.values()].find(t=>t.ms===1500);assert.ok(timer);const polling=timer.fn();h.requests[2].respond({status:'completed',models:[publicDeepSeekModel.id],results:[{id:publicDeepSeekModel.id,status:'verified',message:'已通过真实调用验证'}]});await settle();assert.equal(h.requests[3].url,'/api/models');h.requests[3].respond({models:[{...publicDeepSeekModel,verified:true}]});await polling;assert.equal(h.ui.providers.checking,false);assert.match(h.get('model-check-status').textContent,/真实试答通过回执/);assert.equal(h.get('model-select').disabled,false);
});
test('mismatched trial receipts never mark the selected service verified or automatically repeat a request',async()=>{
 const h=harness();await setPublicModels(h,[publicDeepSeekModel]);const checking=h.ui.checkSelectedModel();h.requests[1].respond({status:'completed',models:['different-codex-model'],results:[{id:'different-codex-model',status:'verified',message:'旧结果'}]});await checking;assert.equal(h.ui.providers.checking,false);assert.match(h.get('model-check-status').textContent,/回执不对应当前模型/);assert.equal(h.requests.length,2);assert.equal(h.get('model-select').children[0].textContent.includes('已核验'),false);
});

test('a mismatched save receipt cannot claim the key was saved',async()=>{
 const h=harness();h.ui.providers.items=publicProviders().providers;h.get('deepseek-api-key').value='synthetic-only';const saving=h.ui.saveDeepSeek({preventDefault(){}});h.requests[0].respond(publicProviders(false));await saving;assert.equal(h.requests.length,1);assert.match(h.get('provider-notice').textContent,/回执与本次操作不一致/);assert.equal(h.get('deepseek-api-key').value,'');
});
test('explicitly stopping a model trial waits for the corresponding stop receipt',async()=>{
 const h=harness();await setPublicModels(h,[publicDeepSeekModel]);const checking=h.ui.checkSelectedModel();h.requests[1].respond({status:'running',models:[publicDeepSeekModel.id],results:[]});await checking;const stopping=h.ui.checkSelectedModel();assert.equal(h.requests[2].url,'/api/models/check/stop');h.requests[2].respond({status:'cancelled',models:[publicDeepSeekModel.id],results:[]});await settle();h.requests[3].respond({models:[publicDeepSeekModel]});await stopping;assert.equal(h.ui.providers.checking,false);assert.match(h.get('model-check-status').textContent,/已停止.*不标记/);assert.equal(h.get('model-select').children[0].textContent.includes('已核验'),false);
});
